INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19201, 'Lamentations 1:4', 'Lamentations', 1, 4, '&nbsp;صيون ته د تلو لارې خالى دى او ماتم کوى، څوک هم ورته اوس د اخترونو دپاره نۀ راځى. د ښار دروازې ټولې خاموشه شوې دى، او د دې اِمامان اسويلى کوى. د هغې پېغلې غمژنې دى، او د هغې تکليفونه تراخۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19202, 'Lamentations 1:5', 'Lamentations', 1, 5, '&nbsp;د هغې دشمنان په هغې اختيارمن شول، او د هغې دشمنان آرام او پُرسکونه ژوند تېروى. مالِک خُدائ داسې ځکه وکړل، چې سرکشى يې ډېره وه. د هغې ماشومان ونيولے شول، او لرې مُلک ته جلاوطن کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19203, 'Lamentations 1:6', 'Lamentations', 1, 6, '&nbsp;د لور صيون ټوله لوئى ختمه شوه، او د هغې نه ټول شان او شوکت لاړو. شهزادګان يې لکه د هغه هوسو په شان شول، چې د څرن ځائ موندلے نۀ شى. هغوئ خو دومره کمزورى شوى وُو، چې د ښکارى نه تښتېدلے نۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19204, 'Lamentations 1:7', 'Lamentations', 1, 7, '&nbsp;يروشلم ښاريې ته هغه وخت ياد دے په کومو ورځو کښې چې زورېدلې او سرګردانه وه، ټول قيمتى څيزونه ورته ياد وُو کوم چې پخوا هغې سره وُو. کله چې هغه د دشمن لاسونو کښې پرېوته، او داسې هيڅ څوک نۀ وُو چې د هغې مدد وکړى، دشمن د هغې د شکست تماشه کوله او د هغې په راغورزېدلو خوشحاله شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19205, 'Lamentations 1:8', 'Lamentations', 1, 8, '&nbsp;يروشلم ښاريې سخته ګناه وکړله او د هغې په وجه پليته شوه. هر چا چې د هغې عزت کولو اوس ورته سپک ګورى ځکه چې دوئ هغه بربنډه او عاجزه وليده. هغه په خپله په زوره زبيرګى کوى او د شرم نه خپل مخ په لاسونو پټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19206, 'Lamentations 1:9', 'Lamentations', 1, 9, '&nbsp;د هغې په لمن د ناپاکۍ داغونه لګېدلى وُو، هغې د خپل اَنجام څۀ سوچ نۀ کولو، د هغې راغورزېدل وحشتناکه وو، څوک داسې نۀ وو چې هغې له تسلى ورکړى. ”مالِکه خُدايه، زما دې تکليفونو ته وګوره، ځکه چې دشمن په ما غالب شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19207, 'Lamentations 1:10', 'Lamentations', 1, 10, '&nbsp;دشمن خپل لاسونه وراوږدۀ کړل او د هغې ټول قيمتى څيزونه يې لوټ کړل. هغې په خپله وليدل چې غېر قومونه د هغې مقدس ځائ ته داخل شول، اګر چې تا دغه خلق خپل جماعت ته د داخلېدو نه منع کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19208, 'Lamentations 1:11', 'Lamentations', 1, 11, '&nbsp;ټولو خلقو يې د روټۍ په تلاش کښې آهونه کول. د خوراک دپاره يې خپل قيمتى څيزونه خرڅ کړل چې پرې خپل ځانونه ژوندى وساتى. ”اے مالِکه خُدايه، ما ته وګوره زۀ څومره سپکه کړے شوې يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19209, 'Lamentations 1:12', 'Lamentations', 1, 12, '&nbsp;ولې ستاسو دپاره دا هيڅ هم نۀ دى، تاسو ټول څوک چې په لاره تېرېږئ؟ راشئ او وګورئ کۀ چرې زما په شان غم او درد بل چرته وى، کوم چې مالِک خُدائ نازل کړو په هغه ورځ چې هغه په قهر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19210, 'Lamentations 1:13', 'Lamentations', 1, 13, '&nbsp;هغۀ بره د آسمان نه اور راولېږلو او هغه زما هډوکو ته ورکوز شو. هغۀ زما پښو ته جال وغوړولو او زۀ يې د تلو نه منع کړم. هغۀ زۀ ګنګس کړې پرېښودم او ټوله ورځ بيماره وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19211, 'Lamentations 1:14', 'Lamentations', 1, 14, '&nbsp;زما سرکشى يو جغ پورې تړلے شوې وه او د هغۀ لاسونو دا تړلى وُو. هغه زما په غاړه بار شو او زما زور يې ختم کړو. مالِک زۀ هغوئ ته حواله کړمه د چا چې زۀ مقابله نۀ شم کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19212, 'Lamentations 1:15', 'Lamentations', 1, 15, '&nbsp;مالِک زما ټول فوجيان رد کړل کوم چې ما سره وُو. هغۀ زما خلاف د لښکر اعلان وکړو چې زما ځوانان غوبل کړى. مالِک د يهوداه نيازبين ښار لکه د انګور په شان په لنګرۍ کښې نچوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19213, 'Lamentations 1:16', 'Lamentations', 1, 16, '&nbsp;نو په دې کارونو زۀ ژړېږم او سترګو نه مې اوښکې بهيږى. نزدې څوک هم نشته چې ما له تسلى راکړى او يا ما له حوصله راکړى. زما ماشومان غمژن شوى دى ځکه دشمن په ما غالب دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19214, 'Lamentations 1:17', 'Lamentations', 1, 17, '&nbsp;صيون خپل لاسونه د مدد دپاره غزوى، خو هيڅ څوک نشته چې تسلى ورکړى. مالِک خُدائ د يعقوب خلاف حکم وکړو چې د هغۀ ګاونډيان به د هغۀ دشمنان شى. د يروشلم نه د هغوئ په مينځ کښې پليته کپړه جوړه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19215, 'Lamentations 1:18', 'Lamentations', 1, 18, '&nbsp;”مالِک خُدائ په حقه دے ځکه ما د هغۀ د حکم نه سرکشى کړې ده. خو اے ټولو خلقو ما ته غوږ شئ، زما غمونو او دردونو ته وګورئ، زما پېغلې ښځې او ځوانان سړى د جلاوطنۍ دپاره بوتلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19216, 'Lamentations 1:19', 'Lamentations', 1, 19, '&nbsp;ما خپلو عاشقانو ته آواز وکړو خو هغوئ ما له دوکه راکړه. کله چې اِمامانو او مشرانو د خپلو ځانونو ژوندى ساتلو دپاره خوراک لټولو نو هغوئ په ښاريه کښې مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19217, 'Lamentations 1:20', 'Lamentations', 1, 20, '&nbsp;وګوره، اے مالِکه خُدايه زۀ څومره زورېدلې يم او زما روح خفه دے او زړۀ مې ناسازه دے ځکه چې زۀ ډېره سرکشه وم. بهر په کوڅو کښې تُورې د بچو نه خلاصه کړم او په کور کښې دننه هم مرګ راپسې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19218, 'Lamentations 1:21', 'Lamentations', 1, 21, '&nbsp;هغوئ واورېدل چې ما څنګه زبيرګى کول خو داسې څوک نشته چې ما له تسلى راکړى. زما ټولو دشمنانو زما د تکليفونو په حقله واورېدل او هغوئ خوشحاله شول چې دا تا په ما راوستى دى. هغه ورځ پرې راوله د کومې چې تا اعلان کړے دے نو هغوئ به هم زما په شان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19219, 'Lamentations 1:22', 'Lamentations', 1, 22, '&nbsp;د هغوئ ټول بدکارونه دې تا ته ښکاره شى. هغوئ له هغسې سزا ورکړه لکه څنګه چې تا ما له زما د ټولې سرکشۍ په وجه راکړې ده. زما کړاونه او زبيرګى زيات دى او زما زړۀ بې‌قراره شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19220, 'Lamentations 2:1', 'Lamentations', 2, 1, '&nbsp;افسوس، مالِک په خپل قهر د لور صيون نيازبين ښار د شرم سره مخ کړو، هغۀ د اِسرائيل شان و شوکت د آسمان نه زمکې ته راوغورزولو. هغۀ په خپل کور باندې هيڅ رحم ونۀ کړو کله چې هغه په قهر او غضب کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19221, 'Lamentations 2:2', 'Lamentations', 2, 2, '&nbsp;مالِک په بې‌رحمۍ سره د يعقوب د اوسېدو ټول ځايونه تباه کړل. او په خپل قهر کښې هغۀ د لور يهوداه د ښار مضبوطې قلعه ګانې راوغورزولې. په بې‌عزتۍ سره هغۀ زمکې ته بادشاهى او د دې بادشاهان راوغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19222, 'Lamentations 2:3', 'Lamentations', 2, 3, '&nbsp;هغۀ په خپل قهر و غضب کښې د اِسرائيلو ټول طاقت ختم کړو. کله چې دشمن حمله وکړه نو مالِک خپل ښے لاس د هغوئ مدد نه وروستو کړو. هغه په اِسرائيل کښې لکه د اور لمبه شو او ګېرچاپېره هر يو شے يې وسوزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19223, 'Lamentations 2:4', 'Lamentations', 2, 4, '&nbsp;هغۀ لکه د دشمن په شان خپله لينده راښکله او هغۀ خپل ښے لاس لکه د دشمن ګزار ته تيار کړو. هغۀ هغه ټول ووژل څوک چې په مونږ ګران وُو، هغۀ خپل غضب لکه د اور په شان د لور صيون په نيازبينې خېمې راوورولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19224, 'Lamentations 2:5', 'Lamentations', 2, 5, '&nbsp;مالِک د هغوئ د دشمن په شان شو، هغۀ اِسرائيل تباه کړو، هغۀ د هغۀ ټول محلونه تباه کړل، د هغۀ مضبوطې قلعه ګانې يې تباه کړې. هغۀ د لور يهوداه ښار په ماتمونو او مرثيو کښې اضافه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19225, 'Lamentations 2:6', 'Lamentations', 2, 6, '&nbsp;هغۀ خپل کور داسې په آسانه راوغورزولو لکه تۀ به وائې چې په باغ کښې يې جونګړه راوغورزوله، او د عبادت مقدس ځائ يې تباه کړو. مالِک خُدائ په صيون مقدس اخترونه او د سبت د ورځو يادونه هېر کړل. په خپل سخت قهر او غضب کښې يې بادشاه او اِمام دواړه رد کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19226, 'Lamentations 2:7', 'Lamentations', 2, 7, '&nbsp;مالِک خپله قربان‌ګاه سپکه کړه، او خپل مقدس مقام يې پرېښودلو. هغۀ د دشمن لاسونو ته د خپل محلونو دېوالونه حواله کړل. دشمن د مالِک خُدائ په کور کښې چغې کړې لکه څنګه چې د اختر په ورځ خلق کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19227, 'Lamentations 2:8', 'Lamentations', 2, 8, '&nbsp;مالِک خُدائ دا فېصله وکړه چې د صيون ښار دېوالونه وران کړى. هغۀ د ورانولو دپاره د ناپ تول ګز راوغزولو او خپل لاس يې د هغۀ د تباهۍ نه منع نۀ کړو. د هغۀ دېوالونه او د هغۀ مورچې يې په ماتم آخته کړې او دواړه په يو ځائ تباه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19228, 'Lamentations 2:9', 'Lamentations', 2, 9, '&nbsp;د يروشلم دروازې په زمکه کښې ډوبې شوې دى، او د هغې اړمونه او تالې يې تباه کړې دى. د هغې بادشاه او شهزادګان نورو قومونو ته جلاوطن کړے شوى دى. نور د مالِک خُدائ نه شريعت نۀ ملاويږى او نۀ نورې وحى د هغۀ پېغمبرانو ته د مالِک خُدائ نه راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19229, 'Lamentations 2:10', 'Lamentations', 2, 10, '&nbsp;د صيون مشران په زمکه په خاموشۍ سره ناست دى. هغوئ په خپلو سرونو خاورې اچولې دى او د ټاټ جامې يې اغوستې دى. د يروشلم پېغلو جينکو خپل سرونه د شرم نه زمکې ته ټيټ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19230, 'Lamentations 2:11', 'Lamentations', 2, 11, '&nbsp;زما سترګې د خفګان نه په ژړا ستړې شوې دى. زما زړۀ د غم نه نا آرامه دے. زما زړۀ د خفګان نه چاؤدلے دے، په دې وجه چې زما خلق تباه شوى دى ځکه چې د پيو او واړۀ ماشومان بې‌هوشه دى او د ښار په سړکونو دپاسه مړاوى کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19231, 'Lamentations 2:12', 'Lamentations', 2, 12, '&nbsp;هغوئ خپلو ميندو ته ژاړى چې، ”خوراک او څښاک چرته دے؟“ هغوئ لکه د زخميانو په شان بې‌حاله دى، د ښار په کوڅو کښې بې‌حاله دى او هغوئ د ژوند نه لاس ووينځلو د مور په غېږ کښې د هغوئ ژوند ختم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19232, 'Lamentations 2:13', 'Lamentations', 2, 13, '&nbsp;زۀ ستا په حقله څۀ ووايم، او د چا سره دې برابره کړمه؟ اے يروشلم لورې، تا د څۀ سره مقايسه کړمه چې تا ته تسلى درکړمه؟ اے صيون پېغلې لورې، د سمندر د ژوروالى په اندازه ستا تباهى ده، څوک به تا ته شفا درکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19233, 'Lamentations 2:14', 'Lamentations', 2, 14, '&nbsp;ستا پېغمبرانو ستا دپاره بې‌مطلبه او دوکه مارې روياګانې وليدلې. هغوئ ستاسو ګناهونه ښکاره نۀ کړل چې تاسو د جلاوطنۍ نه بچ کړى. خو تاسو ته يې د دروغو او بې‌لارې کوونکى پېغامونه واورول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19234, 'Lamentations 2:15', 'Lamentations', 2, 15, '&nbsp;هغوئ ټول څوک چې په دې لاره تېريږى هغوئ تا پورې ملنډى وهى. هغوئ د مسخرو نه خپل سرونه خوځوى او د لور يروشلم ښار پورې خندا کوى. ”آيا دا هغه ښار نۀ وو کوم به چې يادېدو، او په خپل ښائست کښې بې‌عېبه وو، او د ټولې دُنيا د خوشحالۍ سبب وو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19235, 'Lamentations 2:16', 'Lamentations', 2, 16, '&nbsp;ستا ټول دشمنان تا پورې خندا کوى، او ستا خلاف يې خپلې خولې کولاو کړې دى، هغوئ نېغ نېغ ګورى او خپل غاښونه چيچى، او هغوئ چغې وهى چې، ”مونږ هغه لواړه تېره کړه. مونږ د دې ورځ انتظار کولو او آخر مو وليدله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19236, 'Lamentations 2:17', 'Lamentations', 2, 17, '&nbsp;نو مالِک خُدائ خپل مقصد پوره کړو، هغۀ د خپل مقصد خبردارے ورکړو، چې د ډېر پخوا نه يې خبردارے ورکړے وو، هغۀ په بې‌رحمۍ سره هر څۀ تباه کړل. هغۀ ستا دشمنان په تا خوشحاله کړل او هغۀ ستا د دشمنانو زور په تا اوچت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19237, 'Lamentations 2:18', 'Lamentations', 2, 18, '&nbsp;مالِک ته په زوره چغې ووهه، اے د نيازبين صيون لور دېوالونو، د اوښکو نِهرونه دې لکه د سېلاب په شان وبهيږى، په شپه او ورځ کښې دې وبهيږى. خپل ځان ته آرام مۀ ورکوه او په سترګو دې ژړا مۀ بندوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19238, 'Lamentations 2:19', 'Lamentations', 2, 19, '&nbsp;”راپاڅه، او په شپه کښې ژړا وکړه، په هره شېبه کښې د مالِک په حضور کښې د خپل زړۀ حال راڅرګند کړه. او خپل لاسونه هغۀ ته پورته کړه د خپلو ماشومانو د ژوند دپاره څوک چې د کوڅو په هر ګوټ کښې د لوږى نه مړۀ کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19239, 'Lamentations 2:20', 'Lamentations', 2, 20, '&nbsp;وګوره، اے مالِکه خُدايه، او غور وکړه. تا داسې د چا سره کړى دى؟ ولې ميندې دې خپل ماشومان خورى چې هغوئ زيږولى دى؟ ولې اِمامان او پېغمبران دې د مالِک په مقدس کور کښې قتل کړے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19240, 'Lamentations 2:21', 'Lamentations', 2, 21, '&nbsp;زاړۀ او زلمى په کوڅو کښې پراتۀ دى، په زمکه په کوڅو کښې زما ځوانې ښځې او ځوانان سړى په تُوره راغورزولے شوى دى. د خپل قهر په ورځو کښې تا هغوئ مړۀ کړل او په بې‌رحمۍ سره مو حلال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19241, 'Lamentations 2:22', 'Lamentations', 2, 22, '&nbsp;تا د هرې خوا نه زما دشمنانو له دعوت ورکړو لکه چې د اختر د ورځ دپاره دې راغوښتى وى. او د مالِک خُدائ د قهر په ورځو کښې نه څوک تښتېدلے شُو او نه څوک بچ کېدلے شُو. هغوئ څوک چې ما زيږولى وُو او په ما ګران وُو زما دشمن هغه تباه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19242, 'Lamentations 3:1', 'Lamentations', 3, 1, '&nbsp;زۀ هغه کس يم چا چې د مالِک خُدائ د غضب د چُوکې نه تکليفونه ليدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19243, 'Lamentations 3:2', 'Lamentations', 3, 2, '&nbsp;هغۀ زۀ په راښکلو تيارې ته راوستم چې هيڅ رڼا په کښې نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19244, 'Lamentations 3:3', 'Lamentations', 3, 3, '&nbsp;يقيناً چې هغۀ زما په خلاف خپل لاس ټوله ورځ بار بار راوچت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19245, 'Lamentations 3:4', 'Lamentations', 3, 4, '&nbsp;هغۀ زما ټول ځان په وهلو تک شين کړو او زما هډُوکى يې مات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19246, 'Lamentations 3:5', 'Lamentations', 3, 5, '&nbsp;هغۀ زۀ په تريخوالى او غمونو کښې ايسار او راګېر کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19247, 'Lamentations 3:6', 'Lamentations', 3, 6, '&nbsp;هغۀ زۀ په زوړ قبر کښې په توره تياره کښې کښېنولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19248, 'Lamentations 3:7', 'Lamentations', 3, 7, '&nbsp;هغۀ زۀ په دېوالونو کښې راګېر کړم چې ونۀ تښتم او په درنو زنځيرونو يې تړلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19249, 'Lamentations 3:8', 'Lamentations', 3, 8, '&nbsp;تر دې چې ما آواز وکړو او مدد دپاره په چغو وژړېدم، هغۀ زما دُعاګانو ته توجو نۀ ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19250, 'Lamentations 3:9', 'Lamentations', 3, 9, '&nbsp;هغۀ زما لارې د تراشلے شوو کاڼو په دېوال بندې کړى دى، او هغۀ زما لارې ګډې وډې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19251, 'Lamentations 3:10', 'Lamentations', 3, 10, '&nbsp;هغه لکه د مېلو زما په انتظار کښې پروت دے او لکه چې زمرے د حملې دپاره پټ شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19252, 'Lamentations 3:11', 'Lamentations', 3, 11, '&nbsp;هغۀ زۀ د لارې نه بې‌لارې کړم، او ټوټې ټوټې يې کړم. او هغۀ زۀ وران ويجاړ او بې‌ياره بې‌مددګاره پرېښودم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19253, 'Lamentations 3:12', 'Lamentations', 3, 12, '&nbsp;هغۀ خپله لينده راښکله او د خپلو غشو دپاره يې نښه وګرځولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19254, 'Lamentations 3:13', 'Lamentations', 3, 13, '&nbsp;هغۀ زما زړۀ سورے سورے کړو او د خپل تيردان په غشو يې وويشتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19255, 'Lamentations 3:14', 'Lamentations', 3, 14, '&nbsp;زۀ د خپلو خلقو د خندا ذريعه شوم، ټوله ورځ ما ته پيغورونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19256, 'Lamentations 3:15', 'Lamentations', 3, 15, '&nbsp;هغۀ زۀ په ترخو خوراکونو موړ کړم، او د څښلو دپاره يې د تريخ ګنډير نه ډکه پياله راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19257, 'Lamentations 3:16', 'Lamentations', 3, 16, '&nbsp;هغۀ زما په غاښونو کښې باجرى ورکړه، او په خاورو ايرو کښې يې ومنډلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19258, 'Lamentations 3:17', 'Lamentations', 3, 17, '&nbsp;زما زړۀ د سلامتيا نه خالى شوے دے او ما نه هېر دى چې خوشحالى څۀ ته وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19259, 'Lamentations 3:18', 'Lamentations', 3, 18, '&nbsp;نو زۀ دا وايم، ”زما طمع او اُميد لاړو او څۀ چې زما د مالِک خُدائ نه اُميد وو هغه ختم شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19260, 'Lamentations 3:19', 'Lamentations', 3, 19, '&nbsp;زما مصيبتونه او خوار و زار ګرځېدل ما ته ياديږى، او هغه ما ته د ګنډير نه هم تراخۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19261, 'Lamentations 3:20', 'Lamentations', 3, 20, '&nbsp;زۀ بار بار د هغۀ په حقله سوچ کوم او زما روح په ما کښې پرېشانه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19262, 'Lamentations 3:21', 'Lamentations', 3, 21, '&nbsp;خو بيا هم زۀ په خپل سوچ کښې دا راولم او په دې وجه زۀ بيا هم اُميدوار يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19263, 'Lamentations 3:22', 'Lamentations', 3, 22, '&nbsp;د مالِک خُدائ پائيداره مينه هيڅکله نۀ ختميږى او د هغۀ رحم هيڅکله نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19264, 'Lamentations 3:23', 'Lamentations', 3, 23, '&nbsp;د هغۀ رحم او مينه هر سحر نوے او تازه کيږى او د هغۀ وفادارى بې‌شانه لويه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19265, 'Lamentations 3:24', 'Lamentations', 3, 24, '&nbsp;”مالِک خُدائ زما نصيب دے،“ او زۀ خپل ځان ته دا وايم، ”نو په دې وجه زۀ به د هغۀ نه اُميد ساتم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19266, 'Lamentations 3:25', 'Lamentations', 3, 25, '&nbsp;مالِک خُدائ هغه چا سره ښۀ دے څوک چې په هغۀ باور کوى او هغه کس څوک چې د هغۀ تلاش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19267, 'Lamentations 3:26', 'Lamentations', 3, 26, '&nbsp;دا ښۀ ده چې يو کس په خاموشۍ سره انتظار وکړى، د مالِک خُدائ خلاصون ته انتظار وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19268, 'Lamentations 3:27', 'Lamentations', 3, 27, '&nbsp;د يو کس دپاره دا ښۀ ده چې په ځوانۍ کښې جغ يوسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19269, 'Lamentations 3:28', 'Lamentations', 3, 28, '&nbsp;چې په خاموشۍ کښې ځان له کښېنى، څۀ چې مالِک خُدائ پرې اېښے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
