(19271, 'Lamentations 3:30', 'Lamentations', 3, 30, '&nbsp;ظالم ته دې د وهلو دپاره خپل مخ ورواړوى او د هغۀ د لاسه دې بې‌عزتى قبوله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19272, 'Lamentations 3:31', 'Lamentations', 3, 31, '&nbsp;ځکه مالِک به انسان د تل دپاره نۀ رد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19273, 'Lamentations 3:32', 'Lamentations', 3, 32, '&nbsp;دا کۀ هغه غم راولى، هغه به رحم هم کوى، د هغه مينې په مطابق چې ډېره او پائيداره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
