(19276, 'Lamentations 3:35', 'Lamentations', 3, 35, '&nbsp;او کله چې يو انسان د خُدائ تعالىٰ په وړاندې د بل چا حق په زور وهى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
