(19279, 'Lamentations 3:38', 'Lamentations', 3, 38, '&nbsp;ولې د خُدائ تعالىٰ د خوا نه ښۀ او بد دواړه نۀ راځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
