(19283, 'Lamentations 3:42', 'Lamentations', 3, 42, '&nbsp;”مونږ ګناه او سرکشى وکړه او تا مونږ معاف کړى نۀ يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
