(19289, 'Lamentations 3:48', 'Lamentations', 3, 48, '&nbsp;زما د خلقو د تباهۍ په وجه زما د سترګو نه د اوښکو سيندونه بهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19290, 'Lamentations 3:49', 'Lamentations', 3, 49, '&nbsp;زما سترګو نه به اوښکې جارى وى بې له آرام کولو نه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19291, 'Lamentations 3:50', 'Lamentations', 3, 50, '&nbsp;ترڅو چې مالِک خُدائ پاس د آسمان نه نظر واچوى او دا حال وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19292, 'Lamentations 3:51', 'Lamentations', 3, 51, '&nbsp;چې کله زۀ په ښار کښې د ټولو ښځو حالت ګورم نو زما زړۀ غمژن شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19293, 'Lamentations 3:52', 'Lamentations', 3, 52, '&nbsp;هغوئ څوک چې هيڅ بې‌هيڅه زما دشمنان وُو هغوئ لکه د مرغۍ په شان زۀ وويشتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19294, 'Lamentations 3:53', 'Lamentations', 3, 53, '&nbsp;هغوئ زۀ ژوندے په کنده کښې ورواچولم او په ما يې کاڼى راوويشتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19295, 'Lamentations 3:54', 'Lamentations', 3, 54, '&nbsp;اوبۀ زما تر سره راورسېدلې او وئيل مې چې ډوبېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19296, 'Lamentations 3:55', 'Lamentations', 3, 55, '&nbsp;اے مالِکه خُدايه، ما د کندې د بېخ نه ستا په نامه مِنت زارى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19297, 'Lamentations 3:56', 'Lamentations', 3, 56, '&nbsp;تا زما خواست اورېدلے دے، خپل غوږونه مۀ بندوه، د مدد دپاره زما آواز واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19298, 'Lamentations 3:57', 'Lamentations', 3, 57, '&nbsp;تۀ ما ته رانزدې شوې کله چې ما درته آواز وکړو، تا ما ته وفرمائيل چې يرېږه مه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19299, 'Lamentations 3:58', 'Lamentations', 3, 58, '&nbsp;اے مالِکه، تا زما مسئله راوچته کړه او تا زما ژوند بچ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19300, 'Lamentations 3:59', 'Lamentations', 3, 59, '&nbsp;اے مالِکه خُدايه، کوم بد چې ما سره وشُو تا هغه وليدل، زما د مسئلې اِنصاف وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');